import std/strutils
import unittest
import ../../src/rustcrypto/algorithm/halo2
import ../../src/rustcrypto/algorithm/ffi

# Multi-instance-column fixture generated by
# `rustcrypto-ffi/examples/halo2_fixture_multi.rs`
# (K = 10, 2 advice columns, 2 instance columns, 2 public values each).
const Fixture = staticRead("../fixtures/halo2_kzg_bn254_multi_v1.hex")

# magic (8) | column_count (4) | 2 * (value_count (4) + 2 * Fr (32))
const ExpectedInstancesLen = 12 + 2 * (4 + 2 * 32)

proc bytesFromHex(hex: string): seq[byte] =
  ## Local decoder: avoid `./utils` and any installed `rustcrypto` package.
  doAssert hex.len mod 2 == 0
  result = newSeq[byte](hex.len div 2)
  for i in 0 ..< result.len:
    result[i] = byte(parseHexInt(hex[2 * i ..< 2 * i + 2]))

proc fixtureValue(name: string): string =
  for line in Fixture.splitLines:
    let separator = line.find('=')
    if separator > 0 and line[0 ..< separator] == name:
      return line[separator + 1 .. ^1]
  raise newException(ValueError, "missing fixture: " & name)

proc u32Be(data: openArray[byte]; offset: int): uint32 =
  (uint32(data[offset]) shl 24) or
    (uint32(data[offset + 1]) shl 16) or
    (uint32(data[offset + 2]) shl 8) or
    uint32(data[offset + 3])

proc rejected(params, vk, proof, instances: seq[byte]): bool =
  try:
    result = not Halo2KzgBn254.verify(params, vk, proof, instances)
  except ValueError:
    result = true

let
  Params = bytesFromHex(fixtureValue("PARAMS"))
  VerifyingKey = bytesFromHex(fixtureValue("VK"))
  Proof = bytesFromHex(fixtureValue("PROOF"))
  Instances = bytesFromHex(fixtureValue("INSTANCES"))

suite "halo2 kzg bn254 multi-instance-column fixture (blake2b, shplonk)":
  test "fixture encodings are valid":
    check Params.len == Halo2KzgBn254ParamsV1Len
    check Halo2KzgBn254.validateParams(Params)
    check Halo2KzgBn254.validateVerifyingKey(VerifyingKey)
    check Halo2KzgBn254.validatePublicInstances(Instances)

  test "instances encode two columns with two values each":
    check Instances.len == ExpectedInstancesLen
    check Instances[0 ..< 8] == bytesFromHex("5243483249310000")
    check u32Be(Instances, 8) == 2
    check u32Be(Instances, 12) == 2
    check u32Be(Instances, 80) == 2
    # Public values: column 0 = [1, 2], column 1 = [2, 4].
    check Instances[16 + 31] == 1
    check Instances[48 + 31] == 2
    check Instances[84 + 31] == 2
    check Instances[116 + 31] == 4

  test "verifies the known multi-instance proof":
    check Halo2KzgBn254.verify(Params, VerifyingKey, Proof, Instances)

  test "rejects a modified public instance":
    var wrong = Instances
    wrong[^1] = wrong[^1] xor 1
    check rejected(Params, VerifyingKey, Proof, wrong)

  test "rejects a trailing proof byte":
    var trailing = Proof
    trailing.add(0'u8)
    check rejected(Params, VerifyingKey, trailing, Instances)
